if(!exists('counterparty_exposure_backtest',mode='function'))library(creditratingsystem)
dates<-c('2024-01-01','2024-01-02','2024-01-03')
netting<-function(values){agreements<-list(list(netting_set_id='n',counterparty_id='c1',trade_ids=c('a','b'),legally_enforceable=TRUE,evidence_reference='frozen-agreement',known_at=dates[1],effective_from=dates[1],effective_until=NULL),list(netting_set_id='m',counterparty_id='c2',trade_ids='negative',legally_enforceable=FALSE,evidence_reference='singleton',known_at=dates[1],effective_from=dates[1],effective_until=NULL));trades<-fx<-list();for(path in names(values))for(i in seq_along(dates)){date<-dates[i];v<-c(a=values[[path]][i]+60,b=-60,negative=-100);for(trade in names(v))trades[[length(trades)+1]]<-list(path_id=path,date=date,trade_id=trade,currency='EUR',value=unname(v[trade]));fx[[length(fx)+1]]<-list(path_id=path,date=date,currency='EUR',rate=1)};aggregate_netting_set_exposure(trades,agreements,fx,as_of=dates[1],reporting_currency='EUR',valuation_convention='EX_DIVIDEND_BEFORE_MARGIN')$value}
d<-list(model_id='ccr',model_version='1',parameter_version='1',data_fingerprint='frozen-exposures',population_id='counterparties',split_id='holdout',prediction_origin='HOLDOUT',evaluation_cutoff='2024-01-04',currency='EUR',target=list(event='default',horizon=2,time_unit='days',probability_measure='PHYSICAL',conditioning='counterparty_exposure'));forecast<-netting(list(p0=c(40,60,0),p1=c(40,60,20),p2=c(40,60,40),p3=c(40,60,80)));actual<-netting(list(observed=c(40,60,30)));rows<-obs<-list();for(i in 0:1){sid<-c('n','m')[i+1];cp<-c('c1','c2')[i+1];rows[[i+1]]<-list(prediction_id=paste0('f',i),entity_id=cp,cluster_id=cp,segment='ccr',as_of=dates[1],forecast_known_at=dates[1],horizon_end=dates[3],model_id='ccr',model_version='1',parameter_version='1',counterparty_id=cp,netting_set_id=sid,legal_version='1',exposure_target='UNCOLLATERALIZED',netting_paths=forecast);obs[[i+1]]<-list(prediction_id=paste0('f',i),observation_status='OBSERVED',observed_at=dates[3],known_at=dates[3],observed_path_id='observed',legal_version='1',netting_paths=actual,reported_exposure=if(sid=='n')30 else 0)}
run<-function(...)counterparty_exposure_backtest(rows,obs,c(.5,.95),d,...)$value;r<-run(uncertainty='none');stopifnot(r$metrics$market_exposure$bias==2.5,r$diagnostics$forecast_traces[[1]]$quantiles[[1]]$value==20,r$diagnostics$forecast_traces[[1]]$quantiles[[2]]$value==80,r$metrics$quantile_exceptions[[1]]$exception_rate==.5,r$metrics$quantile_exceptions[[1]]$pinball_loss==2.5,r$metrics$conditional_default_closeout$applicability=='NOT_APPLICABLE');r<-run(uncertainty='cluster_bootstrap',cluster_resamples=list(c('c1','c1'),c('c2','c2')));stopifnot(abs(r$uncertainty$intervals[['market_exposure/bias']]$lower-.125)<1e-12,r$uncertainty$intervals[['conditional_default_closeout/bias']]$reason=='NON_ESTIMABLE_RESAMPLE');obs[[1]]$reported_exposure<-0;r<-run(uncertainty='none');stopifnot(r$decision$status=='FAIL',r$coverage$included_count==1,r$diagnostics$reconciliation_violations[[1]]$code=='ILLEGAL_OFFSET_OR_EXPOSURE_RECONCILIATION')
# Real native collateral producer: current exposure0, default-frozen closeout80.
net<-netting(list(p=c(40,60,90)));policies<-market<-calls<-list();for(sid in c('m','n')){policies[[length(policies)+1]]<-list(netting_set_id=sid,known_at=dates[1],collateral_currency='EUR',initial_units=0,threshold_received=0,threshold_posted=0,minimum_transfer_amount=0,ownership='TITLE_TRANSFER',received_enforceable=TRUE,posted_returnability='UNSECURED_CLAIM',posted_claim_netting_enforceable=TRUE,reuse='ALLOWED');for(i in seq_along(dates)){date<-dates[i];market[[length(market)+1]]<-list(path_id='p',date=date,netting_set_id=sid,unit_price=if(i==3).5 else 1,fx_rate=1,received_haircut=0,posted_haircut=0,currency='EUR');calls[[length(calls)+1]]<-list(call_id=paste0(sid,i-1),path_id='p',netting_set_id=sid,call_date=date,valuation_date=date,settlement_date=date,dispute_delay_days=0)}};coll<-simulate_collateral_margin(net,policies,calls,market)$value;rows<-rows[1];obs<-obs[1];event<-list(path_id='p',netting_set_id='n',default_date=dates[1],closeout_date=dates[3],margin_observation_date=dates[1]);flows<-list(list(cashflow_id='unpaid',path_id='p',netting_set_id='n',date=dates[2],amount=10,included_in_closeout_value=FALSE,currency='EUR'));rows[[1]]$exposure_target<-'COLLATERALIZED';rows[[1]]$netting_paths<-net;rows[[1]]$collateral_paths<-coll;rows[[1]]$csa_version<-'1';rows[[1]]$default_events<-list(event);rows[[1]]$intermediate_cashflows<-flows;rows[[1]]$freeze_timing<-'AFTER_DATE_EVENTS';rows[[1]]$cashflow_convention<-'UNSETTLED_EXCLUDED_FROM_CLOSEOUT_VALUE';rows[[1]]$default_sampling_contract<-list(mode='JOINT_SIMULATED_PATHS',known_at=dates[1],reference='tiny-joint-path');obs[[1]]$netting_paths<-net;obs[[1]]$collateral_paths<-coll;obs[[1]]$observed_path_id<-'p';obs[[1]]$csa_version<-'1';obs[[1]]$reported_exposure<-0;obs[[1]]$closeout_event<-event;obs[[1]]$intermediate_cashflows<-flows;obs[[1]]$reported_closeout_exposure<-80;obs[[1]]$closeout_known_at<-'2024-01-04';r<-run(uncertainty='none');stopifnot(r$metrics$market_exposure$mean_outcome==0,r$metrics$conditional_default_closeout$mean_prediction==80,r$metrics$conditional_default_closeout$mean_outcome==80,r$diagnostics$closeout_traces[[1]]$closeout_details$frozen_collateral_units==40);obs[[1]]$observation_status<-'CENSORED';r<-run(uncertainty='none');stopifnot(r$coverage$included_count==0,r$diagnostics$closeout_included_count==1,r$applicability=='APPLICABLE');obs[[1]]$closeout_known_at<-'2024-02-01';r<-run(uncertainty='none');stopifnot(r$metrics$conditional_default_closeout$applicability=='NOT_APPLICABLE')
